# État visuel du bouton IA piloté par le panneau actif.
NEW_FILES = {}
EDITS = [('chrome/browser/ui/views/toolbar/pinned_action_toolbar_button.h', '  void UpdateIcon() override;', '  void UpdateIcon() override;\n  void UpdateColorsAndInsets() override;'), ('chrome/browser/ui/views/toolbar/pinned_action_toolbar_button.cc', '#include "chrome/browser/ui/views/toolbar/pinned_action_toolbar_button.h"', '#include "chrome/browser/ui/views/toolbar/pinned_action_toolbar_button.h"\n#include "chrome/browser/ui/actions/chrome_action_id.h"\n#include "chrome/browser/ui/color/chrome_color_id.h"\n#include "chrome/browser/ui/views/side_panel/glyphe_assistant.h"  // nogncheck\n#include "ui/gfx/color_utils.h"\n#include "ui/gfx/image/image_skia_operations.h"\n#include "ui/views/background.h"\n#include "ui/views/controls/highlight_path_generator.h"\n#include "chrome/browser/themes/theme_service.h"\n#include "chrome/browser/themes/theme_service_factory.h"\n#include "ui/color/glyphe_prism.h"'), ('chrome/browser/ui/views/toolbar/pinned_action_toolbar_button.cc', 'void PinnedActionToolbarButton::UpdateIcon() {', "void PinnedActionToolbarButton::UpdateColorsAndInsets() {\n  ToolbarButton::UpdateColorsAndInsets();\n  if (action_id_ != kActionSidePanelShowGlypheAssistant || !GetColorProvider()) {\n    return;\n  }\n  const auto* colors = GetColorProvider();\n  const bool glyphe_active = IsActive();\n  // Repos : logo monochrome sur pastille discrète. Panneau ouvert : pastille\n  // pleine à l'accent (bleu de la planche), logo de la couleur opposée.\n  // Panneau ouvert : pastille pleine à la couleur du thème (sa pastille dans\n  // Personnaliser, #3450d1 pour Prism) et logo blanc. Repos : logo noir ou\n  // blanc selon le thème, sur une pastille discrète.\n  SkColor seed = ui::kGlyphePrismSeed;\n  if (const ThemeService* theme =\n          ThemeServiceFactory::GetForProfile(browser_->GetProfile());\n      theme && !theme->GetIsGrayscale() && theme->GetUserColor()) {\n    seed = *theme->GetUserColor();\n  }\n  const SkColor icon = glyphe_active\n                           ? SK_ColorWHITE\n                           : colors->GetColor(ui::kColorSysOnSurface);\n  const SkColor background =\n      glyphe_active\n          ? seed\n          : color_utils::AlphaBlend(icon, colors->GetColor(kColorToolbar),\n                                    SkAlpha{0x14});\n  SetBackground(views::CreateRoundedRectBackground(background, 15));\n  // Survol, appui et anneau de focus ronds, comme la pastille.\n  views::InstallCircleHighlightPathGenerator(this);\n  gfx::ImageSkia logo = glyphe::AssistantIcon(\n      glyphe::CurrentAssistant(browser_->GetProfile())).Rasterize(colors);\n  logo = gfx::ImageSkiaOperations::CreateColorMask(logo, icon);\n  for (auto state : {STATE_NORMAL, STATE_HOVERED, STATE_PRESSED}) {\n    SetImageModel(state, ui::ImageModel::FromImageSkia(logo));\n  }\n  if (status_indicator_) {\n    status_indicator_->Hide();\n  }\n}\n\nvoid PinnedActionToolbarButton::UpdateIcon() {\n  if (action_id_ == kActionSidePanelShowGlypheAssistant) {\n    UpdateColorsAndInsets();\n    return;\n  }"), ('chrome/browser/ui/views/toolbar/pinned_action_toolbar_button.cc', '  action_engaged_ = action_engaged;\n  UpdateFlexPriority();', '  action_engaged_ = action_engaged;\n  if (action_id_ == kActionSidePanelShowGlypheAssistant) {\n    UpdateColorsAndInsets();\n  }\n  UpdateFlexPriority();'), ('chrome/browser/ui/views/toolbar/pinned_action_toolbar_button.cc', 'void PinnedActionToolbarButton::UpdateStatusIndicator() {', 'void PinnedActionToolbarButton::UpdateStatusIndicator() {\n  if (action_id_ == kActionSidePanelShowGlypheAssistant) {\n    status_indicator_->Hide();\n    return;\n  }'), ('chrome/browser/ui/views/toolbar/pinned_action_toolbar_button.cc', '  GetViewAccessibility().SetCheckedState(ax::mojom::CheckedState::kTrue);', '  GetViewAccessibility().SetCheckedState(ax::mojom::CheckedState::kTrue);\n  if (action_id_ == kActionSidePanelShowGlypheAssistant) {\n    UpdateColorsAndInsets();\n  }'), ('chrome/browser/ui/views/toolbar/pinned_action_toolbar_button.cc', 'void PinnedActionToolbarButton::ResetHighlight() {\n  anchor_higlight_.reset();\n  GetViewAccessibility().SetCheckedState(ax::mojom::CheckedState::kFalse);', 'void PinnedActionToolbarButton::ResetHighlight() {\n  anchor_higlight_.reset();\n  GetViewAccessibility().SetCheckedState(ax::mojom::CheckedState::kFalse);\n  if (action_id_ == kActionSidePanelShowGlypheAssistant) {\n    UpdateColorsAndInsets();\n  }'), ('chrome/browser/ui/views/toolbar/pinned_action_toolbar_button.cc', '  // Set the accessible name. Fall back to the tooltip if one is not provided.', '  // L’image du modèle est appliquée après SetActionEngaged : reteinter le\n  // logo IA en dernier pour conserver le blanc lorsque le panneau est ouvert.\n  if (action_view_->GetActionId() == kActionSidePanelShowGlypheAssistant) {\n    action_view_->UpdateIcon();\n  }\n  // Set the accessible name. Fall back to the tooltip if one is not provided.')]
